import{_ as e,k as t,v as n}from"./app-Xgp6P-Ux.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";import"./gzh-BO4QB3XE.js";import"./zsxq-BKcsYlFO.js";var i=JSON.parse(`{"path":"/column/Programmingthinking/30-Why-havent-self-driving-cars-become-widespread-yet.html","title":"31-自动驾驶汽车为什么还没有普及？","lang":"zh-CN","frontmatter":{"title":"31-自动驾驶汽车为什么还没有普及？","icon":"read","date":"2025-04-26T08:34:40.000Z","author":"AI悦创","isOriginal":true,"sticky":false,"star":false,"article":true,"timeline":true,"image":false,"navbar":true,"sidebarIcon":true,"comment":true,"lastUpdated":true,"editLink":true,"backToTop":true,"toc":true,"feed":false,"seo":false,"head":[]},"git":{"createdTime":1745628041000,"updatedTime":1745628041000,"contributors":[{"name":"AndersonHJB","username":"AndersonHJB","email":"bornforthis@bornforthis.cn","commits":1,"url":"https://github.com/AndersonHJB"}],"changelog":[{"hash":"78982cdd7701e9137da1888ef2955e8a1a3c3bac","time":1745628041000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"完成"}]},"readingTime":{"minutes":9.94,"words":2983},"filePathRelative":"column/Programmingthinking/30-Why-havent-self-driving-cars-become-widespread-yet.md"}`),a={name:`30-Why-havent-self-driving-cars-become-widespread-yet.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<p>你好，我是悦创。</p><p>如果你喜欢看科幻小说或者是电影，肯定见到过<strong>自动驾驶汽车</strong>的身影。</p><p>比方说<strong>蝙蝠侠</strong>，他的蝙蝠车就有自动驾驶功能。要是在打坏蛋的时候救下了人质，蝙蝠侠就可以让蝙蝠车把人质送到安全的地方去，自己去和坏蛋决一死战。眼看坏蛋就要被打败了，蝙蝠侠又可以先给蝙蝠车下个命令，5分钟后来某某地方接我。这样打完坏蛋蝙蝠侠就可以早早回家吃晚饭了。</p><figure><img src="/assets/72c1d0fdbd2ac47ae98910cef5e19d4f-DmtdienK.jpg" alt="蝙蝠侠战车" tabindex="0" loading="lazy"><figcaption>蝙蝠侠战车</figcaption></figure><p>听起来是不是很酷？你肯定也想有这样一辆自动驾驶的汽车吧？有了这种汽车，以后你们全家出去玩，爸爸妈妈就不用辛苦地开车了，你们可以在车厢里支一个小火锅，全家人吃着火锅唱着歌，别提多开心了！不过我要告诉你，在短时间里，这样的自动驾驶汽车不太可能出现在咱们的生活中。</p><p>你可能会觉得，不对呀，新闻里总是说自动驾驶汽车要来了。难道新闻是骗我们的？听完这集，你就明白是怎么回事了。</p><p>其实，早在<strong>100年前</strong>，科学家们就开始研究自动驾驶汽车了。可因为当时的技术太落后了，搞来搞去，科学家们只搞出了类似于遥控汽车的东西，跟咱们理解的自动驾驶汽车差太远了。</p><figure><img src="/assets/356ee01c4a110915cd7c689bd96aed5d-LMRVKNW7.jpg" alt="有轨电车" tabindex="0" loading="lazy"><figcaption>有轨电车</figcaption></figure><p>和咱们说的自动驾驶技术沾边的，是<strong>1939年</strong>科学家们造出的一款车。这是一款有轨电车，可不是说这车上闹鬼啊，轨是轨道的轨，这种车有点像咱们的<strong>公交车</strong>，但它有固定的轨道，只能沿着轨道开。这款<strong>有轨电车</strong>，可以接收到轨道上传来的电信号，判断前方是不是有其他电车，如果靠得太近了，它还可以自动减速。不过这种车只能在轨道上跑，太不方便了。科学家就开始琢磨，能不能让普通汽车也有自动驾驶功能呢？</p><p>在<strong>1960年前后</strong>，科学家想了个好办法：把公路变成轨道。当然了，他们不是真的要在公路上铺铁轨，而是在公路下面埋上特殊的<strong>电缆</strong>。自动驾驶汽车能接收到电缆发出的信号，顺着电缆前进。后来，科学家还给这个电缆做了升级，不仅可以给汽车指路，还能告诉它，前面有没有其他车辆，帮汽车判断要不要加速减速。这有点自动驾驶的意思了吧？可是按这个思路，咱们要在每条公路下面都铺上这种特殊的电缆，这也太麻烦了。科学家就想，能不能让汽车自己看路，不用电缆给它指路呢？</p><p>没过多久，在<strong>1980年前后</strong>，<strong>雷达</strong>、<strong>摄像头</strong>还有<strong>人工智能技术</strong>逐渐都成熟起来了。科学家们一看，诶，这些东西好啊，雷达和摄像头，可以用来当汽车的眼睛，而人工智能算法可以当汽车的大脑。有了这些技术的帮助，自动驾驶汽车就能自己看见道路，能勉强在没有人的道路上开起来了。</p><p>那到了今天，雷达、摄像头技术更厉害了，人工智能算法也比过去强了许多，自动驾驶技术应该已经成熟了吧？</p><p>确实，现在很多地方，比如<strong>矿山</strong>、<strong>码头</strong>，甚至是一些机场，都已经用起了自动驾驶汽车。但是在咱们生活的城市里，几乎见不到自动驾驶汽车的影子。这是为什么呢？我带你分析分析。</p><figure><img src="/assets/1fb7423103b84d5171482a29f170b65d-t4wSE-1t.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>咱们身边的人工智能，甭管是智能音响、扫地机器人还是自动驾驶汽车，都需要掌握3种能力：<strong>感知、分析判断和执行</strong>。咱们先说第一种能力，<strong>感知</strong>。</p><p>对自动驾驶汽车来说，感知周围的环境并不困难，甚至可以说，它比人类的感知能力还要厉害。比如咱们人类开车的时候，常常会顾前不顾后，顾左不顾右。但自动驾驶汽车就没有这个问题，它的雷达能做到<strong>360度无死角观察</strong>。所以在感知上自动驾驶汽车合格了。</p><p>再说说<strong>执行</strong>。虽然开车是件很不容易的事情，但你可以观察一下，司机在开车时候，要执行的动作类型非常少。最基本的就是踩油门、踩刹车、转方向盘，有了这3个动作，车就能开起来了。再加上其他动作，打转向灯、按喇叭之类的，最多也不会超过10个。</p><p>对自动驾驶汽车来说，执行这10个动作简直是小菜一碟。而且它遇上紧急情况，也不会慌，不会错把油门当刹车。从这一点上来说，它也比人类靠谱，所以在执行上，自动驾驶汽车也合格了。</p><p>最后，还剩<strong>分析判断</strong>这项能力，这是自动驾驶技术里最难的部分。自动驾驶汽车虽然能360度无死角地搜集信息。但在分析这些信息的时候，可能会出错。</p><figure><img src="/assets/ac9316851e5dbee3f38b1c802e3c3235-B_W6i4RW.jpg" alt="自动驾驶汽车" tabindex="0" loading="lazy"><figcaption>自动驾驶汽车</figcaption></figure><p>其实在现实生活中，已经有很多汽车有自动驾驶的系统了，但它们还不能起到完全的自动驾驶功能，只能<strong>辅助</strong>人类驾驶员完成一些简单的操作。</p><p>比如你可能听说过，<strong>特斯拉</strong>汽车的<strong>自动巡航系统</strong>就是这样的辅助系统。在<strong>2016年</strong>的时候，特斯拉的自动巡航系统就出现了一次失误，酿成了一场悲剧。</p><p>事情是这样的，有一位叫布朗的特斯拉车主，他在开车的时候打开了自动巡航系统。</p><p>咱们刚刚说了，这个系统并不是真正意义上的自动驾驶，它可能会做出一些错误的判断，所以需要人类司机在旁边辅助。</p><p>布朗呢，之前也经常用自动巡航功能，从没出过事故。所以这次打开自动巡航之后，他就什么都不管了，在车上看起了“哈利·波特”电影。在这个过程中，汽车的自动巡航系统发出了<strong>7次警报</strong>，提醒布朗要握好方向盘，小心看路。但布朗太放心了，没把警报当回事。结果呢，悲剧发生了。</p><p>布朗的车直直地撞上了一辆白色大货车，布朗当场被撞死了。事故发生后，大家一分析，认为特斯拉的自动巡航系统肯定是看见大货车了，但在分析画面的时候，可能把白色的货车当成了一片白云，所以就直接冲过去了，连刹车都没踩。</p><p>另外，如果布朗听到警报声之后老老实实地握着方向盘看着前方，是可以发现大货车的，轻轻松松就能避开它，可惜的是，他看电影实在是太专心了，这才酿成了悲剧。</p><figure><img src="/assets/cb6a70ee864f1b161f356858ca71d0e5-DaSI-gsx.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>你看，就算自动驾驶汽车在做判断的时候正确率可以达到99.9%，但还是有0.001的可能会出错。</p><p>但对于自动驾驶汽车来说，这0.001至关重要，为什么呢？我们就拿自动驾驶汽车和你熟悉的<strong>家用机器人</strong>做个比较吧。</p><p>如果是家用的清洁机器人判断错误，把你写的暑假作业当成垃圾收走了，你肯定会很生气，但这也不是什么生死攸关的大事。但在路上飞驰的自动驾驶汽车就不一样了，它要是判断失误，就可能会车毁人亡。</p><p>所以，在<strong>分析判断</strong>这项能力上，自动驾驶汽车没能过关。</p><p>听到这你可能会问了，因为这一点点出错的可能性，就放弃自动驾驶，是不是太可惜了？要是科学家一直没想出好的解决办法，难道要一直等下去？</p><p>别着急，对于这种短时间里解决不了的复杂问题，人们早就有一种应对方法，那就是<strong>拆解问题</strong>，一小步一小步地完成。</p><figure><img src="/assets/4346fa0ad5025b0a24d681471a8ba299-jA8G1WZR.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>比方说自动驾驶吧，既然咱们不能一步就造出完美的自动驾驶汽车，就先退一步，造出能够应付<strong>大部分情况</strong>的自动驾驶汽车，科学家管这样的汽车叫有条件的自动驾驶汽车。</p><p>对于比较简单的路况，这种程度的自动驾驶汽车是可以应付的。等到出现了复杂路况，比如周围的车流或者是行人变多了，就交给人类驾驶员处理。</p><p>你在新闻中看到的自动驾驶汽车说的其实就是这个阶段的自动驾驶汽车。这种自动驾驶汽车技术要求没有那么高，人们稍微努努力就能做到。</p><p>等这个技术成熟之后，人类又积累了大量的经验，再去造完全自动驾驶的汽车也就更容易了。</p><p>其实，这种把复杂问题拆分成几个阶段的做法，你在生活中也能用到。假如你想在考试中成为全年级第一名，这听起来就不是件容易的事情。你很可能学着学着就想放弃。这时候你可以把这个目标<strong>拆解</strong>一下。第一个阶段，先补习自己最薄弱的几门学科。第二个阶段，向其他同学请教学习方法，总结出最适合自己的学习方法。做好了前两个阶段，第三个阶段，就可以去争取全年级第一名了。</p><p>好了，到这里，我们在编程思维课里已经讲了很多人工智能的应用，比如打败人类顶尖棋手的<strong>Alpha Go</strong>、战场上的<strong>战争机器人</strong>、<strong>自动驾驶汽车</strong>、<strong>专家系统</strong>等等，它们在很多方面都已经超过了人类的水平。可是，有很多人却说，这些人工智能都很弱。诶，那他们为什么这么说呢？下一集，咱们就来评评理。</p><details class="hint-container details"><summary>公众号：AI悦创【二维码】</summary><figure><img src="/gzh.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure></details><div class="hint-container info"><p class="hint-container-title">AI悦创·编程一对一</p><p>AI悦创·推出辅导班啦，包括「Python 语言辅导班、C++ 辅导班、java 辅导班、算法/数据结构辅导班、少儿编程、pygame 游戏开发、Web、Linux」，招收学员面向国内外，国外占 80%。全部都是一对一教学：一对一辅导 + 一对一答疑 + 布置作业 + 项目实践等。当然，还有线下线上摄影课程、Photoshop、Premiere 一对一教学、QQ、微信在线，随时响应！微信：Jiabcdefh</p><p>C++ 信息奥赛题解，长期更新！长期招收一对一中小学信息奥赛集训，莆田、厦门地区有机会线下上门，其他地区线上。微信：Jiabcdefh</p><p>方法一：<a href="http://wpa.qq.com/msgrd?v=3&amp;uin=1432803776&amp;site=qq&amp;menu=yes" target="_blank" rel="noopener noreferrer">QQ</a></p><p>方法二：微信：Jiabcdefh</p></div><figure><img src="/zsxq.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure>`,44)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};